import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

function Consultation() {
  const [doctors, setDoctors] = useState([
    {
      id: '1',
      name: 'Dr. Lee',
      specialization: 'Cardiology',
      image: 'https://images.unsplash.com/photo-1612349317150-e413f6a5b16d?q=80&w=2970&auto=format&fit=crop',
      description: 'Specialist in heart disease treatments.'
    },
    {
      id: '2',
      name: 'Dr. Wang',
      specialization: 'Neurology',
      image: 'https://images.unsplash.com/photo-1559839734-2b71ea197ec2?q=80&w=2970&auto=format&fit=crop',
      description: 'Expert in brain surgery.'
    },
    {
      id: '3',
      name: 'Dr. Johnson',
      specialization: 'Orthopedics',
      image: 'https://plus.unsplash.com/premium_photo-1658506671316-0b293df7c72b?q=80&w=2970&auto=format&fit=crop',
      description: 'Specialist in orthopedic surgery and sports medicine.'
    }
  ]);
  const [selectedDoctor, setSelectedDoctor] = useState(null);
  const [message, setMessage] = useState('');
  const [loading, setLoading] = useState(true);

  const navigate = useNavigate();
  const userEmail = localStorage.getItem('userEmail');
  const userRole = localStorage.getItem('userRole');

  useEffect(() => {
    // Check user permissions
    if (!userEmail || userRole !== 'client') {
      navigate('/login');
      return;
    }

    setLoading(false);
  }, [userEmail, userRole, navigate]);

  const handleSendMessage = (e) => {
    e.preventDefault();
    if (!selectedDoctor) {
      alert('Please select a doctor first');
      return;
    }

    if (!message.trim()) {
      alert('Please enter a message');
      return;
    }

    // Send consultation message
    // Note: API not implemented yet
    alert(`Consultation functionality not implemented yet.\nDoctor: ${selectedDoctor.name}\nMessage: ${message}`);
    setMessage('');
  };

  if (loading) {
    return <div className="text-center mt-5">Loading...</div>;
  }

  return (
    <>
      <div className="login-background"></div>
      <div className="container mt-5">
        <h2 className="text-center text-white mb-4">Online Doctor Consultation</h2>

        <div className="row">
          <div className="col-md-4">
            <div className="card">
              <div className="card-header bg-primary text-white">
                <h4>Select Doctor</h4>
              </div>
              <div className="card-body">
                <div className="list-group">
                  {doctors.map(doctor => (
                    <button
                      key={doctor.id}
                      className={`list-group-item list-group-item-action ${selectedDoctor?.id === doctor.id ? 'active' : ''}`}
                      onClick={() => setSelectedDoctor(doctor)}
                    >
                      <div className="d-flex align-items-center">
                        <img
                          src={doctor.image}
                          alt={doctor.name}
                          className="rounded-circle me-3"
                          style={{ width: '50px', height: '50px', objectFit: 'cover' }}
                        />
                        <div>
                          <h5 className="mb-1">{doctor.name}</h5>
                          <p className="mb-1 small">{doctor.specialization}</p>
                        </div>
                      </div>
                    </button>
                  ))}
                </div>
              </div>
            </div>
          </div>

          <div className="col-md-8">
            <div className="card">
              <div className="card-header bg-primary text-white">
                <h4>Send Message</h4>
              </div>
              <div className="card-body">
                {selectedDoctor ? (
                  <div>
                    <div className="d-flex align-items-center mb-3">
                      <img
                        src={selectedDoctor.image}
                        alt={selectedDoctor.name}
                        className="rounded-circle me-3"
                        style={{ width: '60px', height: '60px', objectFit: 'cover' }}
                      />
                      <div>
                        <h5>{selectedDoctor.name}</h5>
                        <p className="mb-0">{selectedDoctor.specialization}</p>
                      </div>
                    </div>

                    <p>{selectedDoctor.description}</p>

                    <form onSubmit={handleSendMessage}>
                      <div className="mb-3">
                        <label className="form-label">Message</label>
                        <textarea
                          className="form-control"
                          rows="5"
                          value={message}
                          onChange={(e) => setMessage(e.target.value)}
                          placeholder="Please describe your symptoms or questions..."
                          required
                        ></textarea>
                      </div>
                      <button type="submit" className="btn btn-primary">Send Message</button>
                    </form>
                  </div>
                ) : (
                  <p className="text-center">Please select a doctor from the left to start a consultation.</p>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    </>
  );
}

export default Consultation;
